from solution import find_Product


def test_issue_example():
    """Example: find_Product([1,1,2,3],4) == 6."""
    assert find_Product([1, 1, 2, 3], 4) == 6  # 2*3=6


def test_issue_all_distinct():
    """Product of non-repeated elements includes every element when all are unique."""
    assert find_Product([1, 2, 3, 4], 4) == 24  # 1*2*3*4=24


def test_issue_all_repeated():
    """Product of non-repeated elements with no unique elements is empty product."""
    assert find_Product([2, 2, 3, 3], 4) == 1  # no uniques so empty product=1


def test_issue_single_element():
    """Product of non-repeated elements of a singleton is the element itself."""
    assert find_Product([9], 1) == 9  # 9=9


def test_issue_empty():
    """Product of non-repeated elements of an empty array is empty product."""
    assert find_Product([], 0) == 1  # empty product=1


def test_issue_zero_unique():
    """Product of non-repeated elements includes zero when zero is unique."""
    assert find_Product([0, 2, 2, 3], 4) == 0  # 0*3=0


def test_issue_triple_repeated():
    """Product of non-repeated elements excludes elements appearing three times."""
    assert find_Product([4, 4, 4, 5, 6], 5) == 30  # 5*6=30


def test_issue_negative_unique():
    """Product of non-repeated elements handles negative unique elements."""
    assert find_Product([-2, 2, 2, 3], 4) == -6  # -2*3=-6


def test_contract_permutation_same():
    """Product of non-repeated elements does not depend on order."""
    assert find_Product([3, 2, 1, 1], 4) == 6  # 3*2=6


def test_contract_repeated_zero_excluded():
    """Product of non-repeated elements excludes repeated elements even when zero."""
    assert find_Product([0, 0, 2, 3], 4) == 6  # 2*3=6
